<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <title>롯데월드타워 건축 설계 과정</title>
    <style>
        body { font-family: Arial, sans-serif; }
       .container { display: flex; flex-wrap: wrap; justify-content: center; }
       .drawing { width: 45%; margin: 10px; }
       .model-container { width: 100%; height: 600px; position: relative; }
       .controls { position: absolute; bottom: 10px; left: 10px; background: rgba(255, 255, 255, 0.7); padding: 5px; }
        button { font-size: 19px; margin: 5px; }
    </style>
</head>
<body>
    <div class="container">
        <canvas id="sitePlan" class="drawing"></canvas>
        <canvas id="floorPlan" class="drawing"></canvas>
        <canvas id="elevation" class="drawing"></canvas>
        <canvas id="section" class="drawing"></canvas>
        <div class="model-container">
            <div id="model" class="model"></div>
            <div class="controls">
                <button id="rotateLeft">왼쪽 회전</button>
                <button id="rotateRight">오른쪽 회전</button>
                <button id="zoomIn">확대</button>
                <button id="zoomOut">축소</button>
                <button id="resetView">시점 초기화</button>
            </div>
        </div>
    </div>
    <script src="../runtime/three-runtime.js"></script>
    <script>
        const sitePlanCtx = document.getElementById('sitePlan').getContext('2d');
        const floorPlanCtx = document.getElementById('floorPlan').getContext('2d');
        const elevationCtx = document.getElementById('elevation').getContext('2d');
        const sectionCtx = document.getElementById('section').getContext('2d');

        function drawSitePlan() {
            sitePlanCtx.clearRect(0, 0, sitePlanCtx.canvas.width, sitePlanCtx.canvas.height);
            sitePlanCtx.font = '19px Arial';
            sitePlanCtx.fillText('배치도', 10, 20);
            // Add site plan drawing here
        }

        function drawFloorPlan() {
            floorPlanCtx.clearRect(0, 0, floorPlanCtx.canvas.width, floorPlanCtx.canvas.height);
            floorPlanCtx.font = '19px Arial';
            floorPlanCtx.fillText('기준층 평면도', 10, 20);
            // Add floor plan drawing here
        }

        function drawElevation() {
            elevationCtx.clearRect(0, 0, elevationCtx.canvas.width, elevationCtx.canvas.height);
            elevationCtx.font = '19px Arial';
            elevationCtx.fillText('입면도', 10, 20);
            // Add elevation drawing here
        }

        function drawSection() {
            sectionCtx.clearRect(0, 0, sectionCtx.canvas.width, sectionCtx.canvas.height);
            sectionCtx.font = '19px Arial';
            sectionCtx.fillText('단면도', 10, 20);
            // Add section drawing here
        }

        drawSitePlan();
        drawFloorPlan();
        drawElevation();
        drawSection();

        const modelContainer = document.getElementById('model');
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, modelContainer.offsetWidth / modelContainer.offsetHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer();
        renderer.setSize(modelContainer.offsetWidth, modelContainer.offsetHeight);
        modelContainer.appendChild(renderer.domElement);

        const geometry = new THREE.BoxGeometry();
        const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
        const cube = new THREE.Mesh(geometry, material);
        scene.add(cube);

        camera.position.z = 5;

        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.25;
        controls.enableZoom = true;

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }
        animate();

        document.getElementById('rotateLeft').addEventListener('click', () => {
            cube.rotation.y -= 0.1;
        });

        document.getElementById('rotateRight').addEventListener('click', () => {
            cube.rotation.y += 0.1;
        });

        document.getElementById('zoomIn').addEventListener('click', () => {
            camera.position.z -= 0.1;
        });

        document.getElementById('zoomOut').addEventListener('click', () => {
            camera.position.z += 0.1;
        });

        document.getElementById('resetView').addEventListener('click', () => {
            camera.position.z = 5;
            cube.rotation.y = 0;
        });
    </script>
</body>
</html>
